package com.keplerslicer.app;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import org.json.*;
/** Upstream SimplyPrint public OAuth client; listener is bound exclusively to loopback. */
final class SimplyPrintOAuth implements Closeable {
 static final String CLIENT="simplyprintorcaslicer", SCOPE="user.read files.temp_upload";
 private final URI home,tokenUri; private final String verifier=random(),state=random(),redirect; private final ServerSocket socket; private boolean used;
 SimplyPrintOAuth()throws IOException{this(URI.create("https://simplyprint.io"),URI.create("https://api.simplyprint.io/oauth2/Token"),21328);}
 SimplyPrintOAuth(URI home,URI tokenUri,int port)throws IOException{this.home=home;this.tokenUri=tokenUri;socket=new ServerSocket();socket.setReuseAddress(false);socket.bind(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),port),4);socket.setSoTimeout(500);redirect="http://localhost:"+socket.getLocalPort()+"/callback";}
 URI authorizationUri()throws IOException{try{String challenge=Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII)));return URI.create(home+"/panel/oauth2/authorize?client_id="+enc(CLIENT)+"&redirect_uri="+enc(redirect)+"&scope="+enc(SCOPE)+"&response_type=code&state="+enc(state)+"&code_challenge="+enc(challenge)+"&code_challenge_method=S256");}catch(NoSuchAlgorithmException e){throw new IOException(e);}}
 JSONObject awaitAndExchange(NetworkHttp.Cancellation cancel)throws IOException{if(used)throw new IOException("Запрос входа уже использован.");used=true;if(cancel==null)cancel=new NetworkHttp.Cancellation();String code=null;long deadline=System.nanoTime()+300_000_000_000L;cancel.setCloser(socket);
 try{while(code==null&&System.nanoTime()<deadline){cancel.check();try(Socket peer=socket.accept()){peer.setSoTimeout(3000);String line=readLine(peer.getInputStream());String[] parts=line.split(" ",3);if(parts.length!=3||!parts[0].equals("GET")){answer(peer,400);continue;}URI target;try{target=URI.create(parts[1]);}catch(IllegalArgumentException e){answer(peer,400);continue;}if(!"/callback".equals(target.getPath())||target.getRawAuthority()!=null){answer(peer,404);continue;}Map<String,String> p;try{p=params(target.getRawQuery());}catch(IOException e){answer(peer,400);continue;}if(!MessageDigest.isEqual(state.getBytes(StandardCharsets.UTF_8),p.getOrDefault("state","").getBytes(StandardCharsets.UTF_8))){answer(peer,400);continue;}String next=p.get("code");if(next==null||next.isEmpty()||next.length()>4096){answer(peer,400);throw new IOException("Вход SimplyPrint отклонён.");}code=next;answer(peer,200);}catch(SocketTimeoutException ignored){}}}catch(IOException e){if(cancel.isCancelled())throw new InterruptedIOException("Вход отменён.");throw e;}finally{cancel.clearCloser(socket);socket.close();}
 if(code==null)throw new IOException("Время входа SimplyPrint истекло.");Map<String,String> p=new LinkedHashMap<>();p.put("client_id",CLIENT);p.put("redirect_uri",redirect);p.put("grant_type","authorization_code");p.put("code",code);p.put("code_verifier",verifier);p.put("scope",SCOPE);return request(tokenUri,p,cancel,false);}
 static JSONObject refresh(String refresh,NetworkHttp.Cancellation cancel)throws IOException{return refresh(URI.create("https://api.simplyprint.io/oauth2/Token"),refresh,cancel);}
 static JSONObject refresh(URI uri,String refresh,NetworkHttp.Cancellation cancel)throws IOException{if(refresh==null||refresh.isEmpty())throw new IOException("Отсутствует токен обновления.");Map<String,String> p=new LinkedHashMap<>();p.put("client_id",CLIENT);p.put("grant_type","refresh_token");p.put("refresh_token",refresh);return request(uri,p,cancel,true);}
 private static JSONObject request(URI uri,Map<String,String> p,NetworkHttp.Cancellation cancel,boolean refresh)throws IOException{NetworkHttp.Response r=NetworkHttp.request("POST",uri,Collections.singletonMap("Content-Type","application/x-www-form-urlencoded"),NetworkHttp.bytes(form(p)),cancel);r.requireSuccess();try{JSONObject j=new JSONObject(r.text());if(j.optString("access_token").isEmpty()||(!refresh&&j.optString("refresh_token").isEmpty()))throw new IOException("SimplyPrint не вернул токены.");return j;}catch(JSONException e){throw new IOException("Некорректный ответ SimplyPrint.",e);}}
 static byte[] form(Map<String,String> p){StringBuilder b=new StringBuilder();for(Map.Entry<String,String> e:p.entrySet()){if(b.length()>0)b.append('&');b.append(enc(e.getKey())).append('=').append(enc(e.getValue()));}return b.toString().getBytes(StandardCharsets.US_ASCII);}
 private static String enc(String s){try{return URLEncoder.encode(s,"UTF-8");}catch(UnsupportedEncodingException e){throw new AssertionError(e);}}
 private static String random(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
 private static Map<String,String> params(String q)throws IOException{Map<String,String> m=new HashMap<>();if(q==null)return m;try{for(String a:q.split("&")){String[] p=a.split("=",2);String key=URLDecoder.decode(p[0],"UTF-8"),value=p.length==2?URLDecoder.decode(p[1],"UTF-8"):"";if(m.put(key,value)!=null)throw new IOException("Повторный параметр callback.");}return m;}catch(IllegalArgumentException e){throw new IOException("Некорректный callback.",e);}}
 private static String readLine(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();int c;while((c=in.read())!=-1&&c!='\n'){if(b.size()>=8192)throw new IOException("Слишком длинный callback.");if(c!='\r')b.write(c);}return b.toString("US-ASCII");}
 private static void answer(Socket peer,int status)throws IOException{byte[] b=(status==200?"Authorization received. Return to Kepler Slicer.":"Invalid authorization request.").getBytes(StandardCharsets.UTF_8);OutputStream o=peer.getOutputStream();o.write(("HTTP/1.1 "+status+" Result\r\nContent-Type: text/plain; charset=utf-8\r\nCache-Control: no-store\r\nContent-Length: "+b.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));o.write(b);o.flush();}
 @Override public void close()throws IOException{socket.close();}
}
